-- =============================================================================
-- Base Recruits — Published GPA ranges from schools' Common Data Sets, located
-- with the free College Transitions Common Data Set repository (F51)
--
-- The repository lists 334 schools' Common Data Sets. 239 of them are baseball
-- programs in the registry with a recent document and no GPA range on record.
-- Each school's document was read from the SCHOOL'S OWN website (never the
-- repository's copies), section C11 read twice and checked: the nine bands add
-- to 95–105% and fit the school's printed average. 92 usable ranges.
--
-- Held out (not recorded): Georgia Tech, Georgia, UNC Chapel Hill, Tennessee and
-- William & Mary report weighted GPAs capped in the 4.0 band, so their middle
-- half would be 4.00–4.00 and every unweighted GPA under 4.0 would read "below".
--
-- Some documents print values without band labels; those were matched to the
-- bands in printed order and checked against the printed average (noted per row).
--
-- Additive only. Rollback: delete these rows by unitid.
-- =============================================================================

insert into public.gpa_ranges (unitid, school_name, source_kind, entering_term, cds_year, bands, low, high, average,
                               percent_submitting, source_url, source_title, note)
select s.unitid, s.school_name, 'common_data_set', s.entering_term, s.cds_year, s.bands,
       (private.cds_gpa_middle_half(s.bands))[1], (private.cds_gpa_middle_half(s.bands))[2],
       s.average, s.percent_submitting, s.source_url, s.source_title, s.note
  from (values
  (210669, 'Allegheny College', 'Fall 2025', '2025-2026', array[16.6, 25.7, 23.6, 14.2, 12.2, 7.4, 0.3, 0, 0]::numeric[], 3.59, 95.2,
   'https://sites.allegheny.edu/institutional-effectiveness/files/2026/04/CDS-PDF-2025-2026_PDF_210669.pdf', 'Allegheny College Common Data Set 2025-2026 (PDF)', 'Used the All Enrolled column of the three-column C11 table; confirmed on a second read.'),
